import{_ as s,o as t,c as a,a3 as r}from"./chunks/framework.CRbjHCyB.js";const p=JSON.parse('{"title":"Multi-Process Architecture","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Multi-Process Architecture | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/design/multi-process"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/design/multi-process"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/multi-process"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/multi-process"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/multi-process"}]]},"headers":[],"relativePath":"clice/design/multi-process.md","filePath":"en/clice/design/multi-process.md","lastUpdated":1788607538000}'),o={name:"clice/design/multi-process.md"};function i(n,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="multi-process-architecture" tabindex="-1">Multi-Process Architecture <a class="header-anchor" href="#multi-process-architecture" aria-label="Permalink to &quot;Multi-Process Architecture&quot;">​</a></h1><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>A C++ language server faces a unique engineering challenge: it relies on Clang to parse code, and Clang has many insufficiently tested code paths when handling incomplete or invalid code. Code in the editor is almost always incomplete — missing semicolons, unmatched parentheses, interrupted template instantiations — all scenarios that Clang was not designed to handle robustly. This leads to two serious problems:</p><p><strong>Memory leaks and bloat</strong>: Clang is designed under the assumption that compilation is a short-lived, one-shot operation. The compiler process allocates memory, finishes compilation, and exits; the operating system reclaims everything. But a language server is a long-running process — each user edit triggers recompilation, and Clang&#39;s internally accumulated memory cannot be effectively reclaimed. In the clangd community, users frequently report that the server&#39;s memory usage reaches 10GB+ after running for several hours, eventually being killed by the system&#39;s OOM killer. Typical scenarios include: template-plus-macro combinations causing background indexing to exhaust 16GB of memory; legal code (such as a large array declaration <code>arr[50][6000000]</code>) causing OOM due to constant initialization checks.</p><p><strong>Crashes</strong>: Incomplete code triggers various assertion failures and null pointer dereferences inside Clang. In clangd&#39;s issue tracker, numerous reports involve template instantiation crashes, enum declaration segfaults, corrupted namespaces in catch clauses, and similar scenarios. Because clangd uses a single-process architecture, any single crash terminates the entire language server, causing the user to lose all editing state — even if the crash is only related to one file.</p><p><strong>Priority inversion</strong>: In a single-process / single-thread architecture, background indexing and foreground interactive requests (hover, completion, etc.) compete for the same thread. When background indexing is processing a large file, a user&#39;s hover request may have to wait several seconds for a response. Even with a thread pool, priority control between threads is difficult — the OS thread scheduler does not understand semantics like &quot;the user is waiting for a hover result.&quot;</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><h3 id="core-idea" tabindex="-1">Core Idea <a class="header-anchor" href="#core-idea" aria-label="Permalink to &quot;Core Idea&quot;">​</a></h3><p>clice solves the above problems through a multi-process architecture: each compilation task runs in an independent worker process, and the master process is responsible only for state management and request routing. Worker process crashes or memory leaks are isolated within process boundaries, affecting neither the master process nor other workers.</p><h3 id="process-model" tabindex="-1">Process Model <a class="header-anchor" href="#process-model" aria-label="Permalink to &quot;Process Model&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Master Process (MasterServer)</span></span>
<span class="line"><span>├── Event loop (kota)</span></span>
<span class="line"><span>├── LSP / Agentic protocol handling</span></span>
<span class="line"><span>├── State management (workspace, sessions, invalidation)</span></span>
<span class="line"><span>├── Compile scheduling (task graph: PCH / PCM / AST / TU-run families)</span></span>
<span class="line"><span>├── Background indexing (index store + pump)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Stateful Worker Processes × N</span></span>
<span class="line"><span>│   ├── SF-0: holds AST, serves queries</span></span>
<span class="line"><span>│   ├── SF-1: holds AST, serves queries</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Stateless Worker Processes × M</span></span>
<span class="line"><span>    ├── SL-0: executes one-shot tasks</span></span>
<span class="line"><span>    ├── SL-1: executes one-shot tasks</span></span>
<span class="line"><span>    └── ...</span></span></code></pre></div><p>All worker processes communicate with the master process via stdin/stdout pipes, using bincode serialization (an efficient binary format based on kotatsu&#39;s BincodePeer). Each worker&#39;s stderr is redirected to an independent log file for isolated debugging.</p><h3 id="role-of-the-master-process" tabindex="-1">Role of the Master Process <a class="header-anchor" href="#role-of-the-master-process" aria-label="Permalink to &quot;Role of the Master Process&quot;">​</a></h3><p>The master process is the system&#39;s coordinator, running a single-threaded event loop. It performs no CPU-intensive compilation work — all compilation is delegated to worker processes. The master process is responsible for:</p><ul><li>Receiving and routing LSP / Agentic requests</li><li>Managing global state (Workspace, Session mappings)</li><li>Scheduling compilation tasks and background indexing</li><li>Monitoring worker process health</li><li>Handling file change notifications and cascading updates</li></ul><p>The single-threaded design means the master process requires no locks — all state modifications are executed serially within the event loop. This greatly simplifies state management complexity.</p><h3 id="why-two-kinds-of-worker-processes" tabindex="-1">Why Two Kinds of Worker Processes <a class="header-anchor" href="#why-two-kinds-of-worker-processes" aria-label="Permalink to &quot;Why Two Kinds of Worker Processes&quot;">​</a></h3><p>Language server compilation tasks naturally fall into two categories whose differing characteristics require different scheduling strategies:</p><p><strong>Tasks that need to hold state</strong>: After a user opens a file, they repeatedly query its hover information, semantic highlighting, symbol outline, etc. All of these queries are based on the same AST. If every query triggered recompilation, the latency would be unacceptable (a full compilation can take several seconds). Therefore, the compiled AST must be kept in memory for subsequent queries to reuse. These tasks require <strong>file affinity</strong> — each file is permanently bound to one process.</p><p><strong>One-shot tasks</strong>: PCH builds, PCM builds, background indexing, code completion, signature help, formatting, etc. are all one-shot — no state needs to be retained after execution. These tasks require <strong>load balancing and priority scheduling</strong> — any available worker can execute them, but user-interactive tasks should take priority over background tasks.</p><p>Separating them into two kinds of workers allows each to use the most appropriate scheduling strategy.</p><h2 id="stateful-worker-processes" tabindex="-1">Stateful Worker Processes <a class="header-anchor" href="#stateful-worker-processes" aria-label="Permalink to &quot;Stateful Worker Processes&quot;">​</a></h2><p>The core responsibility of stateful workers is to hold compiled ASTs and serve query requests.</p><h3 id="file-affinity-routing" tabindex="-1">File-Affinity Routing <a class="header-anchor" href="#file-affinity-routing" aria-label="Permalink to &quot;File-Affinity Routing&quot;">​</a></h3><p>Each open file is bound to a stateful worker via its path_id. This binding is stored in the master process&#39;s routing table. When a query request arrives for that file, the master process routes it to the corresponding worker based on the routing table.</p><p>The allocation strategy for new files is <strong>least loaded</strong> — the worker currently owning the fewest documents is selected. This ensures an even distribution of documents across workers.</p><h3 id="compilation-and-query-flow" tabindex="-1">Compilation and Query Flow <a class="header-anchor" href="#compilation-and-query-flow" aria-label="Permalink to &quot;Compilation and Query Flow&quot;">​</a></h3><ol><li>The master process sends CompileParams (source text, compilation flags, PCH/PCM paths, etc.)</li><li>The worker compiles the AST and caches it in an in-memory DocumentEntry</li><li>Subsequent QueryParams (hover, semantic tokens, document symbol, etc.) reuse the cached AST</li><li>When file content changes (didChange), the master process sends a DocumentUpdate notification</li><li>On the next compilation request, the worker recompiles the AST with the new content</li></ol><p>Requests for each document are serialized through a per-document mutex, ensuring that compilation and queries do not run concurrently on the same document.</p><h3 id="document-eviction" tabindex="-1">Document Eviction <a class="header-anchor" href="#document-eviction" aria-label="Permalink to &quot;Document Eviction&quot;">​</a></h3><p>When the number of documents held by a worker exceeds the limit, an LRU strategy evicts the least recently used document, freeing the memory occupied by its AST. The worker sends an eviction notification to the master process. Subsequent requests for that document trigger re-allocation to a worker and recompilation.</p><h2 id="stateless-worker-processes" tabindex="-1">Stateless Worker Processes <a class="header-anchor" href="#stateless-worker-processes" aria-label="Permalink to &quot;Stateless Worker Processes&quot;">​</a></h2><p>Stateless workers execute one-shot compilation tasks using a priority-aware scheduling strategy.</p><h3 id="two-level-priority-queue" tabindex="-1">Two-Level Priority Queue <a class="header-anchor" href="#two-level-priority-queue" aria-label="Permalink to &quot;Two-Level Priority Queue&quot;">​</a></h3><ul><li><strong>High priority</strong>: Work a user request is actively waiting on — interactive builds (code completion, signature help), formatting, and the PCH/PCM builds a foreground request depends on.</li><li><strong>Low priority</strong>: Background indexing runs, which can be deferred without affecting user experience.</li></ul><p>Priority is a property of the dispatch, not of the task type: the same PCH build is dispatched High when a user request is blocked on it and Low when produced by background indexing.</p><p>High-priority tasks always take precedence in acquiring worker resources. Low-priority tasks are subject to a concurrency limit — the number of low-priority tasks running simultaneously has an upper bound, ensuring that workers are always available to handle high-priority requests. Background index runs additionally lower their OS process priority (via the <code>nice</code> system call), reducing their CPU impact on other system processes, including the editor itself.</p><h3 id="dynamic-concurrency-control" tabindex="-1">Dynamic Concurrency Control <a class="header-anchor" href="#dynamic-concurrency-control" aria-label="Permalink to &quot;Dynamic Concurrency Control&quot;">​</a></h3><p>The concurrency cap for low-priority tasks is dynamically adjusted based on system state:</p><p><strong>Foreground-aware budget</strong>: While foreground activity is detected (user requests in flight), background work is capped at roughly 30% of the stateless workers; once the foreground goes idle, background may use full capacity. When foreground activity returns, workers are reclaimed quickly — running low-priority tasks hit cooperative cancellation checkpoints and requeue themselves, with a kill as the timeout fallback — so a burst of typing never waits behind a wall of index builds.</p><p><strong>Memory pressure feedback</strong>: The master process periodically (every 3 seconds) checks available system memory. When available memory drops below 20% of total, the background allowance is decremented by 1; when available memory recovers above 40%, it is incremented by 1. Under severe pressure the allowance can drop all the way to zero, pausing background work entirely.</p><p><strong>Crash backoff</strong>: When a stateless worker crashes, the background allowance is multiplied by 3/4 (multiplicative decrease). Crashes typically indicate encountering code that triggers a Clang bug; continuing at high concurrency risks more workers hitting the same problem. Multiplicative decrease is more aggressive than linear decrease, reducing system load more quickly.</p><p>This combined strategy — a foreground-first budget, linear adjustment for memory pressure, and multiplicative backoff for crashes — ensures graceful degradation under load rather than sudden OOM or cascading crashes.</p><h2 id="crash-recovery" tabindex="-1">Crash Recovery <a class="header-anchor" href="#crash-recovery" aria-label="Permalink to &quot;Crash Recovery&quot;">​</a></h2><p>The core value of process isolation lies in crash recovery — containing a worker&#39;s failure within that process without affecting overall service.</p><h3 id="stateful-worker-crash" tabindex="-1">Stateful Worker Crash <a class="header-anchor" href="#stateful-worker-crash" aria-label="Permalink to &quot;Stateful Worker Crash&quot;">​</a></h3><ol><li>The master process detects the worker exit via a monitoring task</li><li>It clears all bindings for that worker in the routing table</li><li>If the maximum restart count has not been exceeded, a new worker is launched</li><li>Subsequent requests for those documents are automatically routed to the new (or another available) worker and trigger recompilation</li><li>The user may experience a brief delay (the AST needs to be recompiled), but no editing content is lost — the text buffer lives in the master process&#39;s Session</li></ol><h3 id="stateless-worker-crash" tabindex="-1">Stateless Worker Crash <a class="header-anchor" href="#stateless-worker-crash" aria-label="Permalink to &quot;Stateless Worker Crash&quot;">​</a></h3><ol><li>The master process detects the exit</li><li>Crash backoff is triggered, lowering the concurrency cap</li><li>In-flight build requests are resent once to a healthy worker (build tasks are idempotent; a request that kills two workers in a row is treated as poisonous and surfaces its failure instead of retrying forever). Background index attempts are requeued by the scheduler</li><li>If the maximum restart count has not been exceeded, a new worker is launched</li></ol><h3 id="crash-budget-and-revival" tabindex="-1">Crash Budget and Revival <a class="header-anchor" href="#crash-budget-and-revival" aria-label="Permalink to &quot;Crash Budget and Revival&quot;">​</a></h3><p>Each worker slot has a crash budget with exponential backoff between restarts. A stretch of healthy uptime resets the budget, so occasional crashes do not accumulate into a death sentence. A slot that exhausts its budget stops being restarted — but not permanently: after a cooldown period its budget is restored and the slot can be revived on demand. The pool therefore degrades temporarily under systemic failure (fewer workers, slower background indexing) and heals itself once the trigger passes, without ever interrupting the master.</p><h2 id="design-decisions-and-trade-offs" tabindex="-1">Design Decisions and Trade-offs <a class="header-anchor" href="#design-decisions-and-trade-offs" aria-label="Permalink to &quot;Design Decisions and Trade-offs&quot;">​</a></h2><p><strong>Why multi-process instead of multi-threaded?</strong> Threads cannot isolate crashes — a segfault in one thread terminates the entire process. Threads also cannot isolate memory leaks — all threads share the same address space. Multi-process adds IPC overhead (bincode serialization/deserialization) but provides genuine fault isolation. For a library like Clang, which has a known large number of crash and leak paths, process isolation is an engineering necessity.</p><p><strong>Why separate stateful and stateless workers instead of a unified worker pool?</strong> Their scheduling strategies are fundamentally different. Stateful workers need file affinity (to ensure AST reuse); stateless workers need load balancing and priority queues. A unified pool would sacrifice either affinity (causing frequent recompilation) or scheduling flexibility (inability to differentiate priorities). Separating them lets each kind of worker focus on its own scheduling needs.</p><p><strong>Why is the master process single-threaded?</strong> The master process has a light workload — it only performs routing and state management, not compilation. A single thread avoids all concurrency control complexity (locks, atomic operations, race conditions), while a coroutine-based event loop is sufficient for the I/O-intensive routing work.</p><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><p><strong>No per-worker memory enforcement.</strong> Worker memory usage is not capped or watermark-evicted; a pathological translation unit can grow a worker until the operating system&#39;s OOM killer intervenes, at which point normal crash recovery takes over. System-wide memory pressure only throttles background concurrency, it does not bound any single worker.</p></li><li><p><strong>No hang detection.</strong> Worker health is observed through process exit only. A worker stuck inside Clang (an infinite loop rather than a crash) is not detected or restarted automatically; the affected request waits until it is cancelled.</p></li><li><p><strong>Synchronous startup.</strong> Loading the compilation database, warming the toolchain cache, and the initial dependency scan run to completion before the server starts answering requests, and there is no progress reporting yet — on very large projects the server can appear unresponsive for a while right after startup.</p></li></ul>`,57)])])}const g=s(o,[["render",i]]);export{p as __pageData,g as default};
